public theorem smod_result_nonneg {a b : Int64} :
  b > 0 →
  0 <= smod a b ∧ smod a b < b

public theorem sizeOf_lt_of_value [SizeOf α] [SizeOf β] {m : Map α β} {k : α} {v : β}
  (h : (k, v) ∈ m.1) :
  sizeOf v < sizeOf m

public theorem sizeOf_lt_of_find? [SizeOf α] [SizeOf β] [DecidableEq α] {m : Map α β} {k : α} {v : β}
  (h : m.find? k = some v) :
  sizeOf v < sizeOf m

public theorem sizeOf_lt_of_values [SizeOf α] [SizeOf β] {m : Map α β}
  (h : b ∈ m.values) :
  sizeOf b < sizeOf m

public theorem sizeOf_lt_of_tl [SizeOf α] [SizeOf β] {m : Map α β} {tl : List (α × β)}
  (h : m.toList = (k, v) :: tl) :
  1 + sizeOf tl < sizeOf m

public theorem sizeOf_lt_of_mem [SizeOf α] {s : Set α}
  (h : a ∈ s) :
  sizeOf a < sizeOf s

def wildcardMatchIdx (text : List Char) (pattern : Pattern) (i j : Nat)
  (h₁ : i ≤ text.length)
  (h₂ : j ≤ pattern.length) : CacheM Bool

public structure SymTags where  -- for EntityType E:
  keys : UnaryFunction   --   keys: E -> Set String
  vals : UnaryFunction   --   vals: {"entity" : E, "tag" : String} -> T

theorem unchanged_determining_when_add_policy_and_decision_unchanged (request: Request) (entities: Entities) (policies: Policies) (policy₀ : Policy) :
  let auth  := (isAuthorized request entities policies)
  let auth' := (isAuthorized request entities (policy₀ :: policies))
  auth.decision = auth'.decision → auth.determiningPolicies ⊆ auth'.determiningPolicies

theorem error_policies_congr_evaluate {ps : Policies} {r₁ r₂ : Request} {es₁ es₂ : Entities}
  (heq : ∀ p ∈ ps, evaluate p.toExpr r₁ es₁ = evaluate p.toExpr r₂ es₂) :
  errorPolicies ps r₁ es₁ = errorPolicies ps r₂ es₂

theorem is_authorized_congr_evaluate {ps : Policies} {r₁ r₂ : Request} {es₁ es₂ : Entities}
  (heq : ∀ p ∈ ps, evaluate p.toExpr r₁ es₁ = evaluate p.toExpr r₂ es₂) :
  isAuthorized r₁ es₁ ps = isAuthorized r₂ es₂ ps

theorem exists_hasError_of_mem_erroringPolicies {ps : Policies} {request : Request} {entities : Entities} {pid : PolicyID}
  (h : pid ∈ (isAuthorized request entities ps).erroringPolicies) :
  ∃ p ∈ ps, p.id = pid ∧ hasError p request entities = true

theorem principal_scope_false_then_policy_false {p : Policy}
  (hp: evaluate p.principalScope.toExpr req entities = .ok false) :
  evaluate p.toExpr req entities = .ok false

theorem action_scope_false_then_policy_false {p : Policy}
  (ha: evaluate p.actionScope.toExpr req entities = .ok false) :
  evaluate p.toExpr req entities = .ok false

theorem resource_scope_false_then_policy_false {p : Policy}
  (hr : evaluate p.resourceScope.toExpr req entities = .ok false) :
  evaluate p.toExpr req entities = .ok false

theorem record_produces_record_value {rxs : List (Attr × Expr)} {v : Value} {request : Request} {entities : Entities}
  (he : evaluate (.record rxs) request entities = .ok v) :
  ∃ rvs, .record rvs = v

theorem mapM'_asEntityUID_eq_entities {vs : List Value} {euids : List EntityUID}
  (h₁ : List.mapM' Value.asEntityUID vs = Except.ok euids) :
  vs = List.map (Value.prim ∘ Prim.entityUID) euids

theorem batched_evaluate_eq_evaluate
  {x : TypedExpr}
  {req : Request}
  {es : Entities}
  {env : TypeEnv} :
  EntityLoader.WellBehaved es loader →
  TypedExpr.WellTyped env x →
  InstanceOfWellFormedEnvironment req es env →
  (Residual.evaluate (batchedEvaluate env x req loader iters) req es).toOption = (evaluate x.toExpr req es).toOption

theorem environment?_schema {schema : Schema} {pty rty : EntityType} {act : EntityUID}
  {env : TypeEnv} (h : schema.environment? pty rty act = .some env) :
  env.ets = schema.ets ∧ env.acts = schema.acts

theorem actionEntities_refines {env : TypeEnv} {es : Entities}
  (hwf : env.WellFormed) (hinst : InstanceOfSchema es env) :
  EntitiesRefine es (actionEntities env.acts)

public theorem applicative_none  {α β : Type} (f : Option (α → β)) (o : Option α) :
  f = none →
  f <*> o = none

public theorem applicative_of_none {α β : Type} (f : Option (α → β )) (o : Option α) :
  o = none →
  f <*> o = none

public theorem do_some {opt : Option α} {f : α → β} :
  (do let v ← opt ; some (f v)) = some b ↔
  ∃ a, opt = some a ∧ f a = b

public theorem do_error {res : Except ε α} {e : ε} {f : α → β} :
  (do let v ← res ; .ok (f v)) = .error e ↔
  res = .error e

public theorem do_ok_eq_ok {res : Except ε α} {f : α → β} :
  (do let v ← res ; .ok (f v)) = .ok b ↔
  ∃ a, res = .ok a ∧ f a = b

public theorem do_eq_ok {res : Except ε α} {f : α → Except ε β} :
  (do let v ← res ; f v) = .ok b ↔
  ∃ a, res = .ok a ∧ f a = .ok b

public theorem to_option_eq_do₁ {α β ε} {res₁ res₂: Except ε α} (f : α → Except ε β) :
  res₁.toOption = res₂.toOption →
  (do let x ← res₁; f x).toOption = (do let x ← res₂; f x).toOption

theorem Values.lt_conn {vs₁ vs₂ : List Value}
  (h₁ : ¬vs₁ = vs₂) :
  Values.lt vs₁ vs₂ ∨ Values.lt vs₂ vs₁

theorem ValueAttrs.lt_conn {vs₁ vs₂ : List (Attr × Value)}
  (h₁ : ¬vs₁ = vs₂) :
  ValueAttrs.lt vs₁ vs₂ ∨ ValueAttrs.lt vs₂ vs₁

public theorem map_eq_implies_sortedBy [LT β] [StrictLT β] {f : α → β} {g : γ → β} {xs : List α} {ys : List γ} :
  xs.map f = ys.map g →
  (SortedBy f xs ↔ SortedBy g ys)

public theorem filterMap_key_id_sortedBy_key {α β : Type} [LT α] [StrictLT α] [DecidableLT α] {ks : List α} {fn : α → Option β}
  (hs : ks.Sorted) :
  (ks.filterMap (λ k => do (some (k, ←fn k)))).SortedBy Prod.fst

public theorem find?_filterMap_key_id {α β : Type} [BEq α] [LawfulBEq α] {ks : List α} {fn : α → Option β} {k: α}
  (h₂ : k ∈ ks) :
  ((ks.filterMap (λ k => do (k, ←fn k))).find? (λ ⟨k', _⟩ => k' == k)).map Prod.snd = fn k

public theorem insertCanonical_sortedBy [LT β] [StrictLT β] [DecidableLT β] {f : α → β} {xs : List α} (x : α) :
  SortedBy f xs →
  SortedBy f (insertCanonical f x xs)

public theorem insertCanonical_preserves_forallᵥ {α β γ} [LT α] [StrictLT α] [DecidableLT α] {p : β → γ → Prop}
  {kv₁ : α × β} {kv₂ : α × γ} {kvs₁ : List (α × β)} {kvs₂ : List (α × γ)}
  (h₁ : kv₁.fst = kv₂.fst ∧ p kv₁.snd kv₂.snd)
  (h₂ : Forallᵥ p kvs₁ kvs₂) :
  Forallᵥ p (insertCanonical Prod.fst kv₁ kvs₁) (insertCanonical Prod.fst kv₂ kvs₂)

public theorem insertCanonical_map_fst {α β γ} [LT α] [StrictLT α] [DecidableLT α] (xs : List (α × β)) (f : β → γ) (x : α × β) :
  insertCanonical Prod.fst (Prod.map id f x) (map (Prod.map id f) xs) =
  map (Prod.map id f) (insertCanonical Prod.fst x xs)

public theorem insertCanonical_map_fst_canonicalize {α β γ} [LT α] [StrictLT α] [DecidableLT α] (xs : List (α × β)) (f : β → γ) (x : α × β) :
  insertCanonical Prod.fst (Prod.map id f x) (canonicalize Prod.fst (map (Prod.map id f) xs)) =
  map (Prod.map id f) (insertCanonical Prod.fst x (canonicalize Prod.fst xs))

public theorem canonicalize_preserves_forallᵥ {α β γ} [LT α] [StrictLT α] [DecidableLT α] (p : β → γ → Prop) (kvs₁ : List (α × β)) (kvs₂ : List (α × γ)) :
  List.Forallᵥ p kvs₁ kvs₂ →
  List.Forallᵥ p (List.canonicalize Prod.fst kvs₁) (List.canonicalize Prod.fst kvs₂)

public theorem canonicalize_of_map_fst {α β γ} [LT α] [StrictLT α] [DecidableLT α] (xs : List (α × β)) (f : β → γ) :
  List.canonicalize Prod.fst (List.map (Prod.map id f) xs) =
  List.map (Prod.map id f) (List.canonicalize Prod.fst xs)

public theorem map_eq_doubleton {f : α → β} {xs : List α} {y₁ y₂ : β} :
  xs.map f = [y₁, y₂] →
  ∃ x₁ x₂, xs = [x₁, x₂]

public theorem map₁_eq_map (f : α → β) (as : List α) :
  as.map₁ (λ x : {x // x ∈ as} => f x.val) =
  as.map f

public theorem map₂_eq_map {α : Type u} {β : Type v} [SizeOf α] [SizeOf β] {xs : List (α × β)} (f : (α × β) → γ) :
  xs.map₂ (λ x : { x : α × β // sizeOf x.snd < 1 + sizeOf xs } => f x.1) =
  xs.map f

public theorem map₃_eq_map {α : Type u} {β : Type v} [SizeOf α] [SizeOf β] {xs : List (α × β)} (f : (α × β) → γ) :
  xs.map₃ (λ x : { x : α × β // sizeOf x.snd < 1 + (1 + sizeOf xs) } => f x.1) =
  xs.map f

public theorem map₂_eq_map_snd {α : Type u} {β : Type v} [SizeOf α] [SizeOf β] {xs : List (α × β)} (f : β → γ) :
  xs.map₂ (λ x : {x : α × β // sizeOf x.snd < 1 + sizeOf xs } => match x with | ⟨(a, b), _⟩ => (a, f b)) =
  xs.map λ (a, b) => (a, f b)

public theorem map₃_eq_map_snd [SizeOf α] [SizeOf β] {xs : List (α × β)} (f : β → γ) :
  xs.map₃ (λ x : {x : α × β // sizeOf x.snd < 1 + (1 + sizeOf xs) } => match x with | ⟨(a, b), _⟩ => (a, f b)) =
  xs.map λ (a, b) => (a, f b)

public theorem forall₂_implies_all_left {α β} {R : α → β → Prop} {xs : List α} {ys : List β} :
  List.Forall₂ R xs ys →
  ∀ x ∈ xs, ∃ y ∈ ys, R x y

public theorem forall₂_implies_all_right {α β} {R : α → β → Prop} {xs : List α} {ys : List β} :
  List.Forall₂ R xs ys →
  ∀ y ∈ ys, ∃ x ∈ xs, R x y

public theorem forall₂_iff_map_eq {α β γ} {f : α → γ} {g : β → γ} {xs : List α} {ys : List β} :
  List.Forall₂ (λ x y => f x = g y) xs ys ↔
  xs.map f = ys.map g

public theorem map_preserves_forall₂
  {f : α → α'}
  {g : β → β'}
  {p₁ : α → β → Prop}
  {p₂ : α' → β' → Prop}
  {xs : List α} {ys : List β}
  (h : ∀ x y, p₁ x y → p₂ (f x) (g y))
  (hforall₂ : List.Forall₂ p₁ xs ys) :
  List.Forall₂ p₂ (xs.map f) (ys.map g)

public theorem forall₂_compose_mapM_right
  {l₁ : List α} {l₂ : List β} {l₃ : List γ}
  {R₁ : α → β → Prop}
  {R₂ : α → γ → Prop}
  {f : β → Option γ}
  (h : List.Forall₂ R₁ l₁ l₂)
  (hmapM : List.mapM f l₂ = .some l₃)
  (hf : ∀ a b, R₁ a b → ∃ c, f b = .some c ∧ R₂ a c) :
  List.Forall₂ R₂ l₁ l₃

public theorem forall₂_eq_implies_filterMap
  {l₁ : List α} {l₂ : List β} {p : α → β → Prop}
  {f : α → Option β}
  (h : List.Forall₂ p l₁ l₂)
  (hp : ∀ a b, p a b → f a = .some b) :
  l₁.filterMap f = l₂

public theorem mapM₂_eq_map_snd {α : Type u} {β : Type v} [SizeOf α] [SizeOf β] [Monad m] [LawfulMonad m] {xs : List (α × β)} (f : β → m γ) :
  (xs.mapM₂ (λ x : {x : α × β // sizeOf x.snd < 1 + sizeOf xs } => match x with | ⟨(a, b), _⟩ => do pure (a, ← f b))) =
  (xs.mapM λ (a, b) => do pure (a, ← f b))

public theorem mapM_implies_nil {f : α → Except β γ} {as : List α}
  (h₁ : List.mapM f as = Except.ok []) :
  as = []

public theorem mapM_head_tail {α β γ} {f : α → Except β γ} {x : α} {xs : List α} {y : γ} {ys : List γ} :
  (List.mapM f (x :: xs)) = Except.ok (y :: ys) →
  (List.mapM f xs) = Except.ok ys

public theorem mapM'_preserves_length :
  List.mapM' f xs = Except.ok ys →
  xs.length = ys.length

public theorem mapM_preserves_length :
  List.mapM f xs = Except.ok ys →
  xs.length = ys.length

public theorem mapM'_ok_iff_forall₂ {α β γ} {f : α → Except γ β} {xs : List α} {ys : List β} :
  List.mapM' f xs = .ok ys ↔
  List.Forall₂ (λ x y => f x = .ok y) xs ys

public theorem mapM'_some_iff_forall₂ {α β} {f : α → Option β} {xs : List α} {ys : List β} :
  List.mapM' f xs = .some ys ↔
  List.Forall₂ (λ x y => f x = .some y) xs ys

public theorem mapM_ok_iff_forall₂ {α β γ} {f : α → Except γ β} {xs : List α} {ys : List β} :
  List.mapM f xs = .ok ys ↔
  List.Forall₂ (λ x y => f x = .ok y) xs ys

public theorem mapM_some_iff_forall₂ {α β} {f : α → Option β} {xs : List α} {ys : List β} :
  List.mapM f xs = .some ys ↔
  List.Forall₂ (λ x y => f x = .some y) xs ys

public theorem mapM_implies_forall₂
  {f : α → Except ε β}
  {p : α → β → Prop}
  {xs : List α} {ys : List β}
  (h : ∀ x y, x ∈ xs → f x = .ok y → p x y)
  (hmapM : List.mapM f xs = .ok ys) :
  List.Forall₂ p xs ys

public theorem mapM_implies_forall₂_option
  {f : α → Option β}
  {p : α → β → Prop}
  {xs : List α} {ys : List β}
  (h : ∀ x y, x ∈ xs → f x = .some y → p x y)
  (hmapM : List.mapM f xs = .some ys) :
  List.Forall₂ p xs ys

public theorem mapM'_ok_implies_all_ok {α β γ} {f : α → Except γ β} {xs : List α} {ys : List β} :
  List.mapM' f xs = .ok ys →
  ∀ x ∈ xs, ∃ y ∈ ys, f x = .ok y

public theorem mapM_ok_implies_all_ok {α β γ} {f : α → Except γ β} {xs : List α} {ys : List β} :
  List.mapM f xs = .ok ys →
  ∀ x ∈ xs, ∃ y ∈ ys, f x = .ok y

public theorem all_ok_implies_mapM'_ok {α β γ} {f : α → Except γ β} {xs : List α} :
  (∀ x ∈ xs, ∃ y, f x = .ok y) →
  ∃ ys, List.mapM' f xs = .ok ys

public theorem all_ok_implies_mapM_ok {α β γ} {f : α → Except γ β} {xs : List α} :
  (∀ x ∈ xs, ∃ y, f x = .ok y) →
