    (h₁ : ¬ ip.isV6) :
    Term.WellFormedPartialApp εs (Term.app (.ext ExtOp.ipaddr.addrV6) [.prim (.ext (.ipaddr ip))] (.bitvec 128))
  | ext_ipddr_prefix6_wfp {ip : IPAddr}
    (h₁ : ¬ ip.isV6) :
